    (COALESCE(e.emission_co2e_ch4_trww_treated_advanced_aerobic_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_advanced_anaerobic_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_latrine_improved_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_latrine_unimproved_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_primary_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_secondary_aerobic_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_secondary_anaerobic_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_treated_septic_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_untreated_no_sewerage_treatment, 0) + COALESCE(e.emission_co2e_ch4_trww_untreated_with_sewerage_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_advanced_aerobic_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_advanced_aerobic_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_advanced_anaerobic_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_advanced_anaerobic_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_latrine_improved_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_latrine_improved_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_latrine_unimproved_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_latrine_unimproved_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_primary_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_primary_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_secondary_aerobic_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_secondary_aerobic_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_secondary_anaerobic_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_secondary_anaerobic_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_septic_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_treated_septic_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_untreated_no_sewerage_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_untreated_no_sewerage_treatment, 0) + COALESCE(e.emission_co2e_n2o_trww_untreated_with_sewerage_effluent, 0) + COALESCE(e.emission_co2e_n2o_trww_untreated_with_sewerage_treatment, 0)) AS emission_co2e_category_wastewater_treatment,
    (COALESCE(e.emission_co2e_ch4_lndu_wetlands, 0) + COALESCE(e.emission_co2e_co2_lndu_biomass_sequestration_wetlands, 0) + COALESCE(e.emission_co2e_co2_lndu_conversion_wetlands_to_wetlands, 0) + COALESCE(e.emission_co2e_co2_lndu_conversion_flooded_to_flooded, 0)) AS emission_co2e_category_wetlands,
    m.gdp_per_capita_usd * m.population_gnrl_total / 1e9 AS gdp_mmm_usd
FROM decomposed_emissions e
JOIN model_output m
    ON  e.primary_id  = m.primary_id
    AND e.time_period = m.time_period
WHERE e.region = '{region}'
  AND m.region = '{region}'
  AND e.time_period IN (10, 20, 25, 35, 45, 55)
  AND m.time_period IN (10, 20, 25, 35, 45, 55);
